/**
 * MemoryGateway (spec sections 26, 27, 36, 41).
 *
 * The single trusted boundary for every memory operation. It owns two
 * explicitly named store handles (Personal, Business) and chooses exactly one
 * through an exhaustive switch derived from the trusted server-side session —
 * never from client or LLM input. No generic getStore(domainString) exists
 * anywhere below this class.
 */

import { Logger } from "../observability/logging";
import { Metrics } from "../observability/metrics";
import { invalidRequest } from "../core/errors/errors";
import { SecretSanitizer } from "../security/sanitize";
import { normalizeText } from "./ingestion/normalizer";
import { chunkAndEmbed } from "./ingestion/embedder";
import { DedupeService } from "./dedupe";
import { hasSecretLikeContent, expiryForType } from "./policy";
import { DocumentIngestionService } from "./ingestion/service";
import { DocumentService } from "./ingestion/document_service";
import { HybridRetriever } from "./retrieval/hybrid_retriever";
import { contentHash, requestHashOf } from "./provenance";
import {
  DocumentRequest,
  DocumentResult,
  isMemoryType,
  MemoryContext,
  MemoryDomain,
  MemoryItem,
  MemoryItemSummary,
  MemoryListFilter,
  MemorySourceType,
  MemoryStatusReport,
  MemoryWrite,
  MemoryWriteReason,
  RememberRequest,
  RetrievedMemory,
  RetrievalRequest,
  TrustedSessionContext,
  memoryContextFromSession,
  MemoryStore,
  MemoryType,
} from "./contracts";
import type { EmbeddingGateway } from "./embeddings/contracts";
import type { MemoryCandidate } from "./extraction/schemas";
import type { PersonalMemoryStore, BusinessMemoryStore } from "./stores/sqlite_memory_store";

export interface MemoryGateway {
  retrieve(ctx: TrustedSessionContext, request: RetrievalRequest): Promise<RetrievedMemory[]>;
  remember(ctx: TrustedSessionContext, request: RememberRequest): Promise<MemoryItem>;
  ingestDocument(ctx: TrustedSessionContext, request: DocumentRequest, clientRequestId: string): Promise<DocumentResult>;
  forget(ctx: TrustedSessionContext, memoryId: string): Promise<void>;
  list(ctx: TrustedSessionContext, filter: MemoryListFilter): Promise<MemoryItemSummary[]>;
  getDocument(ctx: TrustedSessionContext, documentId: string): Promise<DocumentResult | null>;
  listDocuments(ctx: TrustedSessionContext): Promise<DocumentResult[]>;
  deleteDocument(ctx: TrustedSessionContext, documentId: string): Promise<{ deletedMemories: number; deletedChunks: number }>;
  /** Extraction-path write (conversation candidates), never exposed to clients. */
  storeCandidate(ctx: TrustedSessionContext, candidate: MemoryCandidate & { source_id: string }): Promise<void>;
  status(): MemoryStatusReport;
  close(): void;
}

export interface MemoryGatewayConfig {
  maxChunkTokens: number;
  maxRetrievalCandidates: number;
  maxRerankedResults: number;
  maxContextTokens: number;
  maxSingleChunkTokens: number;
  temporaryTtlSeconds: number;
  maxRememberChars: number;
  embeddingInfo: { provider: string; model: string; version: string; dimensions: number };
}

export interface MemoryGatewayDeps {
  personal: PersonalMemoryStore;
  business: BusinessMemoryStore;
  embeddings: EmbeddingGateway;
  dedupe: DedupeService;
  retriever: HybridRetriever;
  sanitizer: SecretSanitizer;
  config: MemoryGatewayConfig;
  logger?: Logger;
  metrics?: Metrics;
}

export class MemoryGatewayImpl implements MemoryGateway {
  private readonly personal: PersonalMemoryStore;
  private readonly business: BusinessMemoryStore;
  private readonly embeddings: EmbeddingGateway;
  private readonly dedupe: DedupeService;
  private readonly retriever: HybridRetriever;
  private readonly sanitizer: SecretSanitizer;
  private readonly config: MemoryGatewayConfig;
  private readonly logger?: Logger;
  private readonly metrics?: Metrics;
  private readonly ingestionPersonal: DocumentIngestionService;
  private readonly ingestionBusiness: DocumentIngestionService;
  private readonly documentsPersonal: DocumentService;
  private readonly documentsBusiness: DocumentService;

  constructor(deps: MemoryGatewayDeps) {
    this.personal = deps.personal;
    this.business = deps.business;
    this.embeddings = deps.embeddings;
    this.dedupe = deps.dedupe;
    this.retriever = deps.retriever;
    this.sanitizer = deps.sanitizer;
    this.config = deps.config;
    this.logger = deps.logger;
    this.metrics = deps.metrics;
    this.ingestionPersonal = new DocumentIngestionService({
      store: deps.personal,
      embeddings: deps.embeddings,
      sanitizer: deps.sanitizer,
      maxChunkTokens: deps.config.maxChunkTokens,
      logger: deps.logger,
      metrics: deps.metrics,
    });
    this.ingestionBusiness = new DocumentIngestionService({
      store: deps.business,
      embeddings: deps.embeddings,
      sanitizer: deps.sanitizer,
      maxChunkTokens: deps.config.maxChunkTokens,
      logger: deps.logger,
      metrics: deps.metrics,
    });
    this.documentsPersonal = new DocumentService(deps.personal);
    this.documentsBusiness = new DocumentService(deps.business);
  }

  /** The only store selection point: an exhaustive explicit branch. */
  private selectStore(domain: MemoryDomain): MemoryStore {
    if (domain === MemoryDomain.PERSONAL) return this.personal;
    if (domain === MemoryDomain.BUSINESS) return this.business;
    throw new Error(`unknown memory domain: ${String(domain)}`);
  }

  /**
   * Crash repair (spec sections 36, 41): if a write crashed between the item
   * row and its chunk/index rows, re-embed and re-index so the item is
   * retrievable. No-op when chunks already exist.
   */
  private async ensureChunks(store: MemoryStore, item: MemoryItem): Promise<void> {
    const existing = await store.getChunks(item.id);
    if (existing.length > 0) return;
    const { chunks } = await chunkAndEmbed({
      text: item.canonical_text,
      embeddings: this.embeddings,
      maxChunkTokens: this.config.maxChunkTokens,
    });
    await store.putChunks(item.id, chunks);
  }

  private ingestServiceFor(domain: MemoryDomain): DocumentIngestionService {
    if (domain === MemoryDomain.PERSONAL) return this.ingestionPersonal;
    return this.ingestionBusiness;
  }

  private documentsFor(domain: MemoryDomain): DocumentService {
    if (domain === MemoryDomain.PERSONAL) return this.documentsPersonal;
    return this.documentsBusiness;
  }

  async retrieve(ctx: TrustedSessionContext, request: RetrievalRequest): Promise<RetrievedMemory[]> {
    const context = memoryContextFromSession(ctx.session, ctx.trace_id);
    const store = this.selectStore(context.domain);
    try {
      store.expireDue();
    } catch {
      // expiry is opportunistic; retrieval still proceeds
    }
    return this.retriever.retrieve(context, {
      context,
      query_text: request.query_text,
      project_key: request.project_key,
      subject_keys: request.subject_keys,
      allowed_types: request.allowed_types,
      top_k: request.top_k ?? this.config.maxRerankedResults,
      max_context_tokens: request.max_context_tokens ?? this.config.maxContextTokens,
    });
  }

  async remember(ctx: TrustedSessionContext, request: RememberRequest): Promise<MemoryItem> {
    const context = memoryContextFromSession(ctx.session, ctx.trace_id);
    const store = this.selectStore(context.domain);
    const text = normalizeText(request.text);
    if (text === "") throw invalidRequest("memory text is empty");
    if (text.length > this.config.maxRememberChars) {
      throw invalidRequest(`memory text exceeds ${this.config.maxRememberChars} characters`, {
        max_chars: this.config.maxRememberChars,
      });
    }
    if (!isMemoryType(request.type)) throw invalidRequest("memory type is invalid");
    // Secret safety: fail closed before any persistence or embedding.
    if (hasSecretLikeContent(text)) {
      this.metrics?.counter("arthur.memory.write_reason", 1, { reason: "explicit", dedupe_action: "rejected_secret" });
      throw invalidRequest("memory content appears to contain credentials or secret values and was not stored");
    }
    const sanitized = this.sanitizer.sanitizeText(text);
    const requestId = request.client_request_id ? `remember:${request.client_request_id}` : undefined;
    const requestHash = requestId
      ? requestHashOf({
          session_id: ctx.session.id,
          domain: context.domain,
          text: sanitized,
          type: request.type,
          subject_key: request.subject_key ?? null,
          project_key: request.project_key ?? null,
        })
      : undefined;
    const write: MemoryWrite = {
      content_hash: contentHash(sanitized),
      type: request.type,
      subject_key: request.subject_key,
      project_key: request.project_key,
      source_type: MemorySourceType.USER_EXPLICIT,
      // The idempotency key is stamped as provenance so crash reconciliation
      // can recover a completed write that never recorded completion.
      source_id: requestId,
      canonical_text: sanitized,
      display_text: sanitized,
      confidence: 1,
      importance: 0.7,
      sensitivity: "NORMAL",
      expires_at: expiryForType(request.type, this.config.temporaryTtlSeconds),
      embedding_model: "",
      embedding_version: "",
    };

    if (requestId && requestHash !== undefined) {
      const reservation = store.reserveIngestion(requestId, requestHash);
      if (reservation.kind === "conflict") {
        throw invalidRequest("client_request_id was already used for a different memory", {
          client_request_id: request.client_request_id,
        });
      }
      if (reservation.kind === "completed") {
        if (reservation.resultId) {
          const existing = await store.get(reservation.resultId);
          if (existing && existing.status === "ACTIVE") {
            // The first attempt may have crashed between the item row and its
            // chunks; repair the index before replaying (no duplicates).
            await this.ensureChunks(store, existing);
            this.metrics?.counter("arthur.memory.write_reason", 1, { reason: "explicit", dedupe_action: "replayed" });
            return existing;
          }
        }
        // The completed write's item is gone, missing, or no longer ACTIVE
        // (forget is final). Reopen the reservation so this remember creates
        // a fresh ACTIVE memory with the new content — never replays a
        // tombstone (audit F2).
        store.failIngestion(requestId);
      }
      if (!store.beginIngestion(requestId, requestHash)) {
        throw new Error("memory reservation could not be claimed");
      }
    }

    try {
      const outcome = await this.dedupe.resolve(store, write);
      if (outcome.action !== "updated") {
        const { chunks, batch } = await chunkAndEmbed({
          text: sanitized,
          embeddings: this.embeddings,
          maxChunkTokens: this.config.maxChunkTokens,
        });
        await store.putChunks(outcome.item.id, chunks);
        void batch;
      } else {
        // Same-process crash convergence (audit F3): an "updated" replay may
        // hit an ACTIVE item whose chunk/index rows were never written (the
        // first attempt crashed between the item row and putChunks). Rebuild
        // the missing index state so the item is searchable; no-op when the
        // chunks already exist.
        await this.ensureChunks(store, outcome.item);
      }
      if (requestId) store.completeIngestion(requestId, outcome.item.id);
      this.metrics?.counter("arthur.memory.write_reason", 1, { reason: "explicit", dedupe_action: outcome.action });
      return outcome.item;
    } catch (error) {
      if (requestId) store.failIngestion(requestId);
      throw error;
    }
  }

  async storeCandidate(ctx: TrustedSessionContext, candidate: MemoryCandidate & { source_id: string }): Promise<void> {
    const context = memoryContextFromSession(ctx.session, ctx.trace_id);
    const store = this.selectStore(context.domain);
    const text = normalizeText(candidate.text);
    if (text === "" || !isMemoryType(candidate.type)) return;
    if (hasSecretLikeContent(text)) {
      this.metrics?.counter("arthur.memory.write_reason", 1, { reason: "extracted", dedupe_action: "rejected_secret" });
      return;
    }
    const sanitized = this.sanitizer.sanitizeText(text);
    const write: MemoryWrite = {
      content_hash: contentHash(sanitized),
      type: candidate.type,
      subject_key: candidate.subject_key,
      project_key: candidate.project_key,
      source_type: MemorySourceType.CONVERSATION,
      source_id: candidate.source_id,
      canonical_text: sanitized,
      display_text: sanitized,
      confidence: candidate.confidence,
      importance: candidate.importance,
      sensitivity: "NORMAL",
      expires_at: expiryForType(candidate.type, this.config.temporaryTtlSeconds),
      embedding_model: "",
      embedding_version: "",
    };
    const outcome = await this.dedupe.resolve(store, write);
    await this.ensureChunks(store, outcome.item);
    this.metrics?.counter("arthur.memory.write_reason", 1, { reason: "extracted", dedupe_action: outcome.action });
    this.logger?.info("memory candidate stored", {
      domain: context.domain,
      memory_id: outcome.item.id,
      action: outcome.action,
      type: outcome.item.type,
    });
  }

  async ingestDocument(ctx: TrustedSessionContext, request: DocumentRequest, clientRequestId: string): Promise<DocumentResult> {
    const context = memoryContextFromSession(ctx.session, ctx.trace_id);
    const service = this.ingestServiceFor(context.domain);
    return service.ingest({ context, clientRequestId, request });
  }

  async forget(ctx: TrustedSessionContext, memoryId: string): Promise<void> {
    const context = memoryContextFromSession(ctx.session, ctx.trace_id);
    const store = this.selectStore(context.domain);
    try {
      await store.forget(memoryId);
    } catch {
      // Cross-domain or unknown id: never leak which store the id belongs to.
      throw invalidRequest("memory not found in this session's domain", { memory_id: memoryId });
    }
    this.metrics?.counter("arthur.memory.write_reason", 1, { reason: "system", dedupe_action: "deleted" });
  }

  async list(ctx: TrustedSessionContext, filter: MemoryListFilter): Promise<MemoryItemSummary[]> {
    const context = memoryContextFromSession(ctx.session, ctx.trace_id);
    const store = this.selectStore(context.domain);
    return store.list({ ...filter, domain: context.domain });
  }

  async getDocument(ctx: TrustedSessionContext, documentId: string): Promise<DocumentResult | null> {
    const context = memoryContextFromSession(ctx.session, ctx.trace_id);
    return this.documentsFor(context.domain).get(documentId);
  }

  async listDocuments(ctx: TrustedSessionContext): Promise<DocumentResult[]> {
    const context = memoryContextFromSession(ctx.session, ctx.trace_id);
    return this.documentsFor(context.domain).list();
  }

  async deleteDocument(ctx: TrustedSessionContext, documentId: string): Promise<{ deletedMemories: number; deletedChunks: number }> {
    const context = memoryContextFromSession(ctx.session, ctx.trace_id);
    return this.documentsFor(context.domain).delete(documentId);
  }

  status(): MemoryStatusReport {
    return {
      personal: { state: this.personal.health() ? "healthy" : "unavailable" },
      business: { state: this.business.health() ? "healthy" : "unavailable" },
      embedding: { ...this.config.embeddingInfo },
    };
  }

  close(): void {
    this.personal.close();
    this.business.close();
  }
}

/**
 * SQLite-backed memory store (spec sections 7, 11, 13, 14, 33).
 *
 * One store instance == one physical memory database (Personal or Business).
 * The two stores never share a connection or a query object. Each database
 * has its own independent migration chain, schema, FTS index, vector index
 * (embedding blobs) and ingestion idempotency state machine.
 *
 * Isolation is physical: the domain column exists only for validation/audit;
 * the store handle stamps its own domain on every write and every query is
 * scoped to it, so a cross-domain reference can never be created through a
 * shared connection (there is no shared connection).
 */

import { randomUUID } from "node:crypto";
import { mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { DatabaseSync } from "node:sqlite";

import { SecretSanitizer } from "../../security/sanitize";
import { estimateTokens } from "../../observability/usage";
import { buildFtsQuery } from "../retrieval/keyword_search";
import { contentHash } from "../provenance";
import {
  IngestionRecord,
  IngestionReservation,
  KeywordHit,
  KeywordQuery,
  MEMORY_SENSITIVITIES,
  MEMORY_SOURCE_TYPES,
  MEMORY_STATUSES,
  MEMORY_TYPES,
  MemoryChunk,
  MemoryChunkWrite,
  MemoryDomain,
  MemoryItem,
  MemoryItemSummary,
  MemoryListFilter,
  MemorySourceRecord,
  MemoryStore,
  MemoryWrite,
  VectorHit,
  VectorQuery,
} from "../contracts";
import { cosineSimilarity } from "../embeddings/contracts";

interface Migration {
  version: number;
  name: string;
  up: string | ((db: DatabaseSync) => void);
}

function tableExists(db: DatabaseSync, table: string): boolean {
  return Boolean(db.prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?").get(table));
}

const nowIso = (): string => new Date().toISOString();

const MIGRATIONS: Migration[] = [
  {
    version: 1,
    name: "memory_schema",
    up: (db: DatabaseSync): void => {
      db.exec(`
        CREATE TABLE IF NOT EXISTS memory_items (
          id TEXT PRIMARY KEY,
          domain TEXT NOT NULL CHECK(domain IN ('personal','business')),
          type TEXT NOT NULL CHECK(type IN ('EPISODIC','SEMANTIC','PROJECT','DOCUMENT','PROCEDURAL','TEMPORARY')),
          source_type TEXT NOT NULL CHECK(source_type IN ('USER_EXPLICIT','CONVERSATION','DOCUMENT','TOOL','SYSTEM')),
          source_id TEXT,
          subject_key TEXT,
          project_key TEXT,
          canonical_text TEXT NOT NULL,
          display_text TEXT NOT NULL,
          content_hash TEXT NOT NULL,
          confidence REAL NOT NULL CHECK(confidence >= 0 AND confidence <= 1),
          importance REAL NOT NULL CHECK(importance >= 0 AND importance <= 1),
          sensitivity TEXT NOT NULL CHECK(sensitivity IN ('NORMAL','PRIVATE','RESTRICTED')),
          status TEXT NOT NULL CHECK(status IN ('ACTIVE','SUPERSEDED','DELETED','EXPIRED')),
          supersedes_id TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL,
          last_verified_at TEXT,
          expires_at TEXT,
          embedding_model TEXT NOT NULL,
          embedding_version TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_items_status ON memory_items(status, expires_at);
        CREATE INDEX IF NOT EXISTS idx_items_project ON memory_items(status, project_key);
        CREATE INDEX IF NOT EXISTS idx_items_subject ON memory_items(status, subject_key, type);
        CREATE INDEX IF NOT EXISTS idx_items_source ON memory_items(source_id);
        CREATE UNIQUE INDEX IF NOT EXISTS uq_items_active_hash ON memory_items(content_hash) WHERE status = 'ACTIVE';

        CREATE TABLE IF NOT EXISTS memory_chunks (
          id TEXT PRIMARY KEY,
          memory_id TEXT NOT NULL REFERENCES memory_items(id) ON DELETE CASCADE,
          ordinal INTEGER NOT NULL,
          text TEXT NOT NULL,
          token_count INTEGER NOT NULL CHECK(token_count >= 0),
          content_hash TEXT NOT NULL,
          embedding_blob BLOB,
          UNIQUE(memory_id, ordinal)
        );
        CREATE INDEX IF NOT EXISTS idx_chunks_memory ON memory_chunks(memory_id);

        CREATE TABLE IF NOT EXISTS memory_sources (
          id TEXT PRIMARY KEY,
          source_type TEXT NOT NULL CHECK(source_type IN ('USER_EXPLICIT','CONVERSATION','DOCUMENT','TOOL','SYSTEM')),
          source_external_id TEXT,
          title TEXT,
          source_hash TEXT NOT NULL,
          metadata_json TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );
        CREATE UNIQUE INDEX IF NOT EXISTS uq_sources_hash ON memory_sources(source_hash);

        CREATE TABLE IF NOT EXISTS ingestion_requests (
          request_id TEXT PRIMARY KEY,
          request_hash TEXT NOT NULL,
          state TEXT NOT NULL CHECK(state IN ('pending','writing','completed','failed')),
          result_id TEXT,
          created_at TEXT NOT NULL,
          updated_at TEXT NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_ingestion_state ON ingestion_requests(state);
      `);
      // FTS index is a separate virtual table (spec section 14).
      db.exec(`CREATE VIRTUAL TABLE IF NOT EXISTS memory_fts5 USING fts5(
        chunk_id UNINDEXED,
        memory_id UNINDEXED,
        text,
        tokenize = 'unicode61'
      )`);
    },
  },
];

function validateSchema(db: DatabaseSync): void {
  const required: Record<string, string[]> = {
    memory_items: ["id", "domain", "type", "source_type", "canonical_text", "display_text", "content_hash", "confidence", "importance", "sensitivity", "status", "created_at", "updated_at", "embedding_model", "embedding_version"],
    memory_chunks: ["id", "memory_id", "ordinal", "text", "token_count", "content_hash"],
    memory_sources: ["id", "source_type", "source_hash", "created_at", "updated_at"],
    ingestion_requests: ["request_id", "request_hash", "state", "created_at", "updated_at"],
  };
  for (const [table, columns] of Object.entries(required)) {
    const actual = new Set(
      (db.prepare(`PRAGMA table_info(${table})`).all() as Array<{ name: string }>).map((row) => row.name),
    );
    if (columns.some((column) => !actual.has(column))) {
      throw new Error(`Memory schema validation failed for ${table}`);
    }
  }
  const fts = db.prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'memory_fts5'").get();
  if (!fts) throw new Error("Memory schema validation failed for memory_fts5");
}

function embedBlob(vector: number[] | undefined): Buffer | null {
  if (!vector || vector.length === 0) return null;
  const f32 = Float32Array.from(vector);
  return Buffer.from(f32.buffer);
}

function blobToVector(blob: unknown): number[] | undefined {
  if (blob === null || blob === undefined) return undefined;
  const buffer = Buffer.isBuffer(blob) ? blob : Buffer.from(blob as Uint8Array);
  return Array.from(new Float32Array(buffer.buffer, buffer.byteOffset, buffer.byteLength / 4));
}

const CHUNK_ID_SEPARATOR = "#";

function chunkId(memoryId: string, ordinal: number): string {
  return `${memoryId}${CHUNK_ID_SEPARATOR}${ordinal}`;
}

export class SqliteMemoryStore implements MemoryStore {
  private db: DatabaseSync;
  private readonly domainValue: MemoryDomain;
  private readonly sanitizer: SecretSanitizer;

  constructor(dbPath: string, domain: MemoryDomain, sanitizer: SecretSanitizer = new SecretSanitizer([])) {
    this.domainValue = domain;
    this.sanitizer = sanitizer;
    const target = dbPath === ":memory:" ? ":memory:" : resolve(dbPath);
    if (target !== ":memory:") {
      mkdirSync(dirname(target), { recursive: true });
    }
    this.db = new DatabaseSync(target, { enableForeignKeyConstraints: true });
    try {
      this.db.exec("PRAGMA busy_timeout = 10000;");
      this.migrate();
      if (target !== ":memory:") {
        this.db.exec("PRAGMA journal_mode = WAL;");
      }
      this.db.exec("PRAGMA synchronous = NORMAL;");
      this.reconcileIngestions();
      this.expireDue();
    } catch (error) {
      this.db.close();
      throw error;
    }
  }

  domain(): MemoryDomain {
    return this.domainValue;
  }

  transaction<T>(fn: () => T): T {
    this.db.exec("BEGIN IMMEDIATE");
    try {
      const result = fn();
      this.db.exec("COMMIT");
      return result;
    } catch (err) {
      this.db.exec("ROLLBACK");
      throw err;
    }
  }

  private execWithBusyRetry(sql: string): void {
    for (let attempt = 0; ; attempt++) {
      try {
        this.db.exec(sql);
        return;
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        if (attempt >= 40 || !/locked|busy/i.test(message)) throw error;
        Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 25);
      }
    }
  }

  private migrate(): void {
    this.execWithBusyRetry("BEGIN IMMEDIATE");
    try {
      this.db.exec("CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, name TEXT NOT NULL)");
      const rows = this.db.prepare("SELECT version FROM schema_migrations").all() as Array<{ version: number }>;
      const applied = new Set(rows.map((r) => r.version));
      for (const migration of MIGRATIONS) {
        if (applied.has(migration.version)) continue;
        if (typeof migration.up === "string") this.db.exec(migration.up);
        else migration.up(this.db);
        this.db.prepare("INSERT INTO schema_migrations (version, name) VALUES (?, ?)").run(migration.version, migration.name);
      }
      validateSchema(this.db);
      this.db.exec("COMMIT");
    } catch (err) {
      this.db.exec("ROLLBACK");
      throw err;
    }
  }

  // ---- items ---------------------------------------------------------------

  async put(item: MemoryWrite): Promise<MemoryItem> {
    const confidence = item.confidence;
    const importance = item.importance;
    if (!(confidence >= 0 && confidence <= 1)) throw new Error("memory confidence must be within 0..1");
    if (!(importance >= 0 && importance <= 1)) throw new Error("memory importance must be within 0..1");
    // putNow performs the insert with idempotent convergence (spec section 33).
    return this.putNow(item);
  }

  async get(id: string): Promise<MemoryItem | null> {
    const row = this.db.prepare("SELECT * FROM memory_items WHERE id = ? AND domain = ?").get(id, this.domainValue) as
      | Record<string, unknown>
      | undefined;
    if (!row) return null;
    return this.toItem(row);
  }

  private toItem(row: Record<string, unknown>): MemoryItem {
    return {
      id: String(row.id),
      domain: row.domain as MemoryDomain,
      type: row.type as MemoryItem["type"],
      subject_key: row.subject_key === null ? undefined : String(row.subject_key),
      project_key: row.project_key === null ? undefined : String(row.project_key),
      source_type: row.source_type as MemoryItem["source_type"],
      source_id: row.source_id === null ? undefined : String(row.source_id),
      canonical_text: String(row.canonical_text),
      display_text: String(row.display_text),
      content_hash: String(row.content_hash),
      confidence: Number(row.confidence),
      importance: Number(row.importance),
      sensitivity: row.sensitivity as MemoryItem["sensitivity"],
      status: row.status as MemoryItem["status"],
      supersedes_id: row.supersedes_id === null ? undefined : String(row.supersedes_id),
      created_at: String(row.created_at),
      updated_at: String(row.updated_at),
      last_verified_at: row.last_verified_at === null ? undefined : String(row.last_verified_at),
      expires_at: row.expires_at === null ? undefined : String(row.expires_at),
      embedding_model: String(row.embedding_model),
      embedding_version: String(row.embedding_version),
    };
  }

  private toSummary(row: Record<string, unknown>): MemoryItemSummary {
    return {
      id: String(row.id),
      type: row.type as MemoryItemSummary["type"],
      text: String(row.display_text),
      status: row.status as MemoryItemSummary["status"],
      confidence: Number(row.confidence),
      importance: Number(row.importance),
      source_type: row.source_type as MemoryItemSummary["source_type"],
      source_id: row.source_id === null ? undefined : String(row.source_id),
      subject_key: row.subject_key === null ? undefined : String(row.subject_key),
      project_key: row.project_key === null ? undefined : String(row.project_key),
      created_at: String(row.created_at),
      updated_at: String(row.updated_at),
    };
  }

  async list(filter: MemoryListFilter): Promise<MemoryItemSummary[]> {
    const clauses = ["domain = ?"];
    const params: Array<string | number | null> = [this.domainValue];
    const status = filter.status ?? "ACTIVE";
    clauses.push("AND status = ?");
    params.push(status);
    if (filter.type !== undefined) {
      clauses.push("AND type = ?");
      params.push(filter.type);
    }
    if (filter.project_key !== undefined) {
      clauses.push("AND project_key = ?");
      params.push(filter.project_key);
    }
    if (filter.subject_key !== undefined) {
      clauses.push("AND subject_key = ?");
      params.push(filter.subject_key);
    }
    clauses.push("ORDER BY created_at DESC, rowid DESC");
    const limit = Math.min(filter.limit ?? 100, 1000);
    const offset = filter.offset ?? 0;
    clauses.push("LIMIT ? OFFSET ?");
    params.push(limit, offset);
    const rows = this.db.prepare(`SELECT * FROM memory_items WHERE ${clauses.join(" ")}`).all(...params) as unknown as Array<Record<string, unknown>>;
    return rows.map((row) => this.toSummary(row));
  }

  async findActiveByHash(contentHashHex: string): Promise<MemoryItem | null> {
    const row = this.db
      .prepare("SELECT * FROM memory_items WHERE domain = ? AND status = 'ACTIVE' AND content_hash = ? LIMIT 1")
      .get(this.domainValue, contentHashHex) as Record<string, unknown> | undefined;
    return row ? this.toItem(row) : null;
  }

  async findActiveBySubject(subjectKey: string, type: MemoryItem["type"]): Promise<MemoryItem[]> {
    const rows = this.db
      .prepare(
        `SELECT * FROM memory_items
         WHERE domain = ? AND status = 'ACTIVE' AND subject_key = ? AND type = ?
         ORDER BY created_at DESC, rowid DESC LIMIT 20`,
      )
      .all(this.domainValue, subjectKey, type) as unknown as Array<Record<string, unknown>>;
    return rows.map((row) => this.toItem(row));
  }

  async supersede(oldId: string, replacement: MemoryWrite): Promise<MemoryItem> {
    return this.transaction(() => {
      const changed = this.db
        .prepare(
          "UPDATE memory_items SET status = 'SUPERSEDED', updated_at = ? WHERE id = ? AND domain = ? AND status = 'ACTIVE'",
        )
        .run(nowIso(), oldId, this.domainValue);
      if (Number(changed.changes) !== 1) {
        throw new Error(`cannot supersede ${oldId}: no active memory with that id in the ${this.domainValue} store`);
      }
      const withLink: MemoryWrite = { ...replacement, supersedes_id: oldId };
      // put() is synchronous against the same DatabaseSync handle; awaiting here
      // keeps the transaction scope correct for callers.
      const item = this.putNow(withLink);
      return item;
    });
  }

  /** Synchronous put used inside transactions. Idempotent: an insert that
   *  collides with an existing row (same id, or same active content_hash from
   *  a concurrent duplicate write) converges on the existing row instead of
   *  failing — this is what makes concurrent/duplicate ingestion safe. */
  private putNow(item: MemoryWrite): MemoryItem {
    const id = item.id ?? randomUUID();
    const now = nowIso();
    const insert = this.db
      .prepare(
        `INSERT OR IGNORE INTO memory_items (
           id, domain, type, source_type, source_id, subject_key, project_key,
           canonical_text, display_text, content_hash, confidence, importance,
           sensitivity, status, supersedes_id, created_at, updated_at,
           last_verified_at, expires_at, embedding_model, embedding_version
         ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'ACTIVE', ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        id,
        this.domainValue,
        item.type,
        item.source_type,
        item.source_id ?? null,
        item.subject_key ?? null,
        item.project_key ?? null,
        this.sanitizer.sanitizeText(item.canonical_text),
        this.sanitizer.sanitizeText(item.display_text),
        item.content_hash,
        item.confidence,
        item.importance,
        item.sensitivity ?? "NORMAL",
        item.supersedes_id ?? null,
        now,
        now,
        now,
        item.expires_at ?? null,
        item.embedding_model,
        item.embedding_version,
      );
    if (Number(insert.changes) === 0) {
      const byId = this.db
        .prepare("SELECT * FROM memory_items WHERE id = ? AND domain = ?")
        .get(id, this.domainValue) as Record<string, unknown> | undefined;
      if (byId) return this.toItem(byId);
      const byHash = this.db
        .prepare("SELECT * FROM memory_items WHERE domain = ? AND status = 'ACTIVE' AND content_hash = ? LIMIT 1")
        .get(this.domainValue, item.content_hash) as Record<string, unknown> | undefined;
      if (byHash) return this.toItem(byHash);
      throw new Error(`memory item insert was ignored without a matching row (id=${id})`);
    }
    return this.getNow(id);
  }

  private getNow(id: string): MemoryItem {
    const row = this.db.prepare("SELECT * FROM memory_items WHERE id = ? AND domain = ?").get(id, this.domainValue) as
      | Record<string, unknown>
      | undefined;
    if (!row) throw new Error(`memory item not found after write: ${id}`);
    return this.toItem(row);
  }

  async forget(id: string): Promise<void> {
    this.transaction(() => {
      const tombstone = `[deleted:${id}]`;
      const changed = this.db
        .prepare(
          `UPDATE memory_items SET status = 'DELETED', canonical_text = ?, display_text = ?,
             content_hash = ?, updated_at = ?
           WHERE id = ? AND domain = ? AND status != 'DELETED'`,
        )
        .run(tombstone, tombstone, contentHash(tombstone), nowIso(), id, this.domainValue);
      if (Number(changed.changes) !== 1) {
        throw new Error(`cannot forget ${id}: no memory with that id in the ${this.domainValue} store`);
      }
      this.db.prepare("DELETE FROM memory_chunks WHERE memory_id = ?").run(id);
      this.db.prepare("DELETE FROM memory_fts5 WHERE memory_id = ?").run(id);
    });
  }

  async touchVerified(id: string): Promise<void> {
    this.db
      .prepare("UPDATE memory_items SET last_verified_at = ?, updated_at = ? WHERE id = ? AND status = 'ACTIVE'")
      .run(nowIso(), nowIso(), id);
  }

  expireDue(): number {
    const result = this.db
      .prepare(
        "UPDATE memory_items SET status = 'EXPIRED', updated_at = ? WHERE status = 'ACTIVE' AND expires_at IS NOT NULL AND expires_at <= ?",
      )
      .run(nowIso(), nowIso());
    return Number(result.changes);
  }

  // ---- chunks / vector index ------------------------------------------------

  async putChunks(memoryId: string, chunks: MemoryChunkWrite[]): Promise<void> {
    this.transaction(() => {
      this.db.prepare("DELETE FROM memory_fts5 WHERE memory_id = ?").run(memoryId);
      for (const chunk of chunks) {
        const id = chunkId(memoryId, chunk.ordinal);
        this.db
          .prepare(
            `INSERT OR IGNORE INTO memory_chunks (id, memory_id, ordinal, text, token_count, content_hash, embedding_blob)
             VALUES (?, ?, ?, ?, ?, ?, ?)`,
          )
          .run(
            id,
            memoryId,
            chunk.ordinal,
            this.sanitizer.sanitizeText(chunk.text),
            chunk.token_count,
            chunk.content_hash,
            embedBlob(chunk.embedding),
          );
        this.db
          .prepare("INSERT OR REPLACE INTO memory_fts5 (chunk_id, memory_id, text) VALUES (?, ?, ?)")
          .run(id, memoryId, this.sanitizer.sanitizeText(chunk.text));
      }
    });
  }

  async writeDocumentAtomic(input: {
    source: MemorySourceRecord;
    item: MemoryWrite;
    chunks: MemoryChunkWrite[];
  }): Promise<void> {
    const { source, item, chunks } = input;
    this.transaction(() => {
      const now = nowIso();
      this.db
        .prepare(
          `INSERT OR IGNORE INTO memory_sources (id, source_type, source_external_id, title, source_hash, metadata_json, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          source.id,
          source.source_type,
          source.source_external_id ?? null,
          source.title ?? null,
          source.source_hash,
          source.metadata_json ?? null,
          source.created_at,
          now,
        );
      this.db
        .prepare("UPDATE memory_sources SET title = ?, metadata_json = ?, updated_at = ? WHERE id = ?")
        .run(source.title ?? null, source.metadata_json ?? null, now, source.id);
      this.putNow({
        ...item,
        id: item.id ?? randomUUID(),
        canonical_text: this.sanitizer.sanitizeText(item.canonical_text),
        display_text: this.sanitizer.sanitizeText(item.display_text),
      });
      this.db.prepare("DELETE FROM memory_fts5 WHERE memory_id = ?").run(item.id ?? "");
      for (const chunk of chunks) {
        const id = chunkId(item.id ?? "", chunk.ordinal);
        this.db
          .prepare(
            `INSERT OR IGNORE INTO memory_chunks (id, memory_id, ordinal, text, token_count, content_hash, embedding_blob)
             VALUES (?, ?, ?, ?, ?, ?, ?)`,
          )
          .run(
            id,
            item.id ?? "",
            chunk.ordinal,
            this.sanitizer.sanitizeText(chunk.text),
            chunk.token_count,
            chunk.content_hash,
            embedBlob(chunk.embedding),
          );
        this.db
          .prepare("INSERT OR REPLACE INTO memory_fts5 (chunk_id, memory_id, text) VALUES (?, ?, ?)")
          .run(id, item.id ?? "", this.sanitizer.sanitizeText(chunk.text));
      }
    });
  }

  async getChunks(memoryId: string): Promise<MemoryChunk[]> {
    const rows = this.db
      .prepare("SELECT * FROM memory_chunks WHERE memory_id = ? ORDER BY ordinal ASC")
      .all(memoryId) as unknown as Array<Record<string, unknown>>;
    return rows.map((row) => ({
      id: String(row.id),
      memory_id: String(row.memory_id),
      ordinal: Number(row.ordinal),
      text: String(row.text),
      token_count: Number(row.token_count),
      content_hash: String(row.content_hash),
      embedding: blobToVector(row.embedding_blob),
    }));
  }

  async deleteChunks(memoryId: string): Promise<void> {
    this.transaction(() => {
      this.db.prepare("DELETE FROM memory_chunks WHERE memory_id = ?").run(memoryId);
      this.db.prepare("DELETE FROM memory_fts5 WHERE memory_id = ?").run(memoryId);
    });
  }

  // ---- vector search (spec section 13) --------------------------------------

  async vectorSearch(query: VectorQuery): Promise<VectorHit[]> {
    const now = nowIso();
    const clauses = ["c.memory_id IS NOT NULL", "i.domain = ?", "i.status = 'ACTIVE'", "(i.expires_at IS NULL OR i.expires_at > ?)"];
    const params: Array<string | number | null> = [this.domainValue, now];
    if (query.filters.project_key !== undefined) {
      clauses.push("i.project_key = ?");
      params.push(query.filters.project_key);
    }
    if (query.filters.subject_keys !== undefined && query.filters.subject_keys.length > 0) {
      clauses.push(`i.subject_key IN (${query.filters.subject_keys.map(() => "?").join(",")})`);
      params.push(...query.filters.subject_keys);
    }
    if (query.filters.allowed_types !== undefined && query.filters.allowed_types.length > 0) {
      clauses.push(`i.type IN (${query.filters.allowed_types.map(() => "?").join(",")})`);
      params.push(...query.filters.allowed_types);
    }
    const rows = this.db
      .prepare(
        `SELECT c.id AS chunk_id, c.memory_id, c.text, c.embedding_blob
         FROM memory_chunks c JOIN memory_items i ON i.id = c.memory_id
         WHERE ${clauses.join(" AND ")}
         ORDER BY c.rowid ASC LIMIT 5000`,
      )
      .all(...params) as unknown as Array<{ chunk_id: string; memory_id: string; text: string; embedding_blob: unknown }>;

    const minSimilarity = query.min_similarity ?? 0;
    const scored: VectorHit[] = [];
    for (const row of rows) {
      const vector = blobToVector(row.embedding_blob);
      if (!vector || vector.length === 0) continue;
      const score = cosineSimilarity(query.vector, vector);
      // Minimum similarity guard: weak matches are not candidates (they are
      // not "semantically relevant", spec section 15.2).
      if (score < minSimilarity) continue;
      scored.push({ chunk_id: row.chunk_id, memory_id: row.memory_id, text: row.text, score });
    }
    scored.sort((a, b) => b.score - a.score || (a.memory_id < b.memory_id ? -1 : 1));
    return scored.slice(0, query.limit);
  }

  // ---- keyword / FTS search (spec section 14) --------------------------------

  async keywordSearch(query: KeywordQuery): Promise<KeywordHit[]> {
    const ftsQuery = buildFtsQuery(query.text);
    if (ftsQuery === "") return [];
    const now = nowIso();
    const clauses = ["memory_fts5 MATCH ?", "i.domain = ?", "i.status = 'ACTIVE'", "(i.expires_at IS NULL OR i.expires_at > ?)"];
    const params: Array<string | number | null> = [ftsQuery, this.domainValue, now];
    if (query.filters.project_key !== undefined) {
      clauses.push("i.project_key = ?");
      params.push(query.filters.project_key);
    }
    if (query.filters.subject_keys !== undefined && query.filters.subject_keys.length > 0) {
      clauses.push(`i.subject_key IN (${query.filters.subject_keys.map(() => "?").join(",")})`);
      params.push(...query.filters.subject_keys);
    }
    if (query.filters.allowed_types !== undefined && query.filters.allowed_types.length > 0) {
      clauses.push(`i.type IN (${query.filters.allowed_types.map(() => "?").join(",")})`);
      params.push(...query.filters.allowed_types);
    }
    const rows = this.db
      .prepare(
        `SELECT f.chunk_id, f.memory_id, c.text, bm25(memory_fts5) AS raw_rank
         FROM memory_fts5 f
         JOIN memory_chunks c ON c.id = f.chunk_id
         JOIN memory_items i ON i.id = c.memory_id
         WHERE ${clauses.join(" AND ")}
         ORDER BY raw_rank ASC LIMIT ?`,
      )
      .all(...params, query.limit) as unknown as Array<{ chunk_id: string; memory_id: string; text: string; raw_rank: number }>;
    return rows.map((row) => ({
      chunk_id: row.chunk_id,
      memory_id: row.memory_id,
      text: row.text,
      score: -row.raw_rank,
    }));
  }

  // ---- sources / documents ----------------------------------------------------

  async putSource(source: MemorySourceRecord): Promise<void> {
    const now = nowIso();
    this.db
      .prepare(
        `INSERT OR IGNORE INTO memory_sources (id, source_type, source_external_id, title, source_hash, metadata_json, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        source.id,
        source.source_type,
        source.source_external_id ?? null,
        source.title ?? null,
        source.source_hash,
        source.metadata_json ?? null,
        source.created_at,
        now,
      );
    // Re-ingesting identical content updates metadata (title/project) without duplicating.
    this.db
      .prepare("UPDATE memory_sources SET title = ?, metadata_json = ?, updated_at = ? WHERE id = ?")
      .run(source.title ?? null, source.metadata_json ?? null, now, source.id);
  }

  async getSource(id: string): Promise<MemorySourceRecord | null> {
    const row = this.db.prepare("SELECT * FROM memory_sources WHERE id = ?").get(id) as Record<string, unknown> | undefined;
    if (!row) return null;
    return {
      id: String(row.id),
      source_type: row.source_type as MemorySourceRecord["source_type"],
      source_external_id: row.source_external_id === null ? undefined : String(row.source_external_id),
      title: row.title === null ? undefined : String(row.title),
      source_hash: String(row.source_hash),
      metadata_json: row.metadata_json === null ? undefined : String(row.metadata_json),
      created_at: String(row.created_at),
      updated_at: String(row.updated_at),
    };
  }

  async listSources(): Promise<MemorySourceRecord[]> {
    const rows = this.db.prepare("SELECT * FROM memory_sources ORDER BY created_at ASC").all() as unknown as Array<Record<string, unknown>>;
    return rows.map((row) => ({
      id: String(row.id),
      source_type: row.source_type as MemorySourceRecord["source_type"],
      source_external_id: row.source_external_id === null ? undefined : String(row.source_external_id),
      title: row.title === null ? undefined : String(row.title),
      source_hash: String(row.source_hash),
      metadata_json: row.metadata_json === null ? undefined : String(row.metadata_json),
      created_at: String(row.created_at),
      updated_at: String(row.updated_at),
    }));
  }

  async deleteSource(id: string): Promise<{ deletedMemories: number; deletedChunks: number }> {
    return this.transaction(() => {
      const items = this.db.prepare("SELECT id FROM memory_items WHERE source_id = ?").all(id) as unknown as Array<{ id: string }>;
      const tombstone = `[deleted:${id}]`;
      let deletedChunks = 0;
      for (const item of items) {
        this.db
          .prepare(
            `UPDATE memory_items SET status = 'DELETED', canonical_text = ?, display_text = ?,
               content_hash = ?, updated_at = ?
             WHERE id = ? AND status != 'DELETED'`,
          )
          .run(tombstone, tombstone, contentHash(`${tombstone}:${item.id}`), nowIso(), item.id);
        const chunkResult = this.db.prepare("DELETE FROM memory_chunks WHERE memory_id = ?").run(item.id);
        deletedChunks += Number(chunkResult.changes);
        this.db.prepare("DELETE FROM memory_fts5 WHERE memory_id = ?").run(item.id);
      }
      this.db.prepare("DELETE FROM memory_sources WHERE id = ?").run(id);
      return { deletedMemories: items.length, deletedChunks };
    });
  }

  // ---- ingestion idempotency (spec section 33) --------------------------------

  reserveIngestion(requestId: string, requestHash: string): IngestionReservation {
    const now = nowIso();
    this.db
      .prepare(
        "INSERT OR IGNORE INTO ingestion_requests (request_id, request_hash, state, created_at, updated_at) VALUES (?, ?, 'pending', ?, ?)",
      )
      .run(requestId, requestHash, now, now);
    const record = this.getIngestion(requestId);
    if (!record) return { kind: "proceed" };
    if (record.request_hash !== requestHash) return { kind: "conflict" };
    if (record.state === "completed" && record.result_id) {
      return { kind: "completed", resultId: record.result_id };
    }
    // pending/writing/failed with the same hash may be resumed (crash recovery).
    return { kind: "proceed" };
  }

  beginIngestion(requestId: string, requestHash: string): boolean {
    const result = this.db
      .prepare(
        `UPDATE ingestion_requests SET state = 'writing', updated_at = ?
         WHERE request_id = ? AND request_hash = ? AND state IN ('pending','writing','failed')`,
      )
      .run(nowIso(), requestId, requestHash);
    return Number(result.changes) === 1;
  }

  completeIngestion(requestId: string, resultId: string): void {
    this.db
      .prepare(
        "UPDATE ingestion_requests SET state = 'completed', result_id = ?, updated_at = ? WHERE request_id = ? AND request_hash IS NOT NULL",
      )
      .run(resultId, nowIso(), requestId);
  }

  failIngestion(requestId: string): void {
    this.db
      .prepare("UPDATE ingestion_requests SET state = 'failed', updated_at = ? WHERE request_id = ?")
      .run(nowIso(), requestId);
  }

  getIngestion(requestId: string): IngestionRecord | null {
    const row = this.db.prepare("SELECT * FROM ingestion_requests WHERE request_id = ?").get(requestId) as Record<string, unknown> | undefined;
    if (!row) return null;
    return {
      request_id: String(row.request_id),
      request_hash: String(row.request_hash),
      state: row.state as IngestionRecord["state"],
      result_id: row.result_id === null ? undefined : String(row.result_id),
      created_at: String(row.created_at),
      updated_at: String(row.updated_at),
    };
  }

  /** Crash reconciliation (spec section 36): interrupted writes whose result
   *  already exists converge to completed. The result is located by result_id
   *  when recorded, or by the request_id stamped on memory_items.source_id;
   *  when found that way the result_id is backfilled so replays resolve. */
  reconcileIngestions(): string[] {
    const now = nowIso();
    const rows = this.db
      .prepare("SELECT request_id FROM ingestion_requests WHERE state IN ('pending','writing')")
      .all() as unknown as Array<{ request_id: string }>;
    const recovered: string[] = [];
    for (const row of rows) {
      const record = this.getIngestion(row.request_id);
      if (!record) continue;
      const found = this.db
        .prepare("SELECT id FROM memory_items WHERE (id = ? OR source_id = ?) AND status = 'ACTIVE' LIMIT 1")
        .get(record.result_id ?? "", record.request_id) as { id: string } | undefined;
      if (found) {
        this.db
          .prepare("UPDATE ingestion_requests SET state = 'completed', result_id = ?, updated_at = ? WHERE request_id = ?")
          .run(found.id, now, record.request_id);
        recovered.push(record.request_id);
      }
    }
    return recovered;
  }

  health(): boolean {
    try {
      this.db.prepare("SELECT 1").get();
      return true;
    } catch {
      return false;
    }
  }

  close(): void {
    try {
      this.db.close();
    } catch {
      // closing twice is a no-op
    }
  }
}

// ---- Explicit named store handles (spec sections 4, 7) -----------------------

export class PersonalMemoryStore extends SqliteMemoryStore {
  constructor(dbPath: string, sanitizer: SecretSanitizer = new SecretSanitizer([])) {
    super(dbPath, MemoryDomain.PERSONAL, sanitizer);
  }
}

export class BusinessMemoryStore extends SqliteMemoryStore {
  constructor(dbPath: string, sanitizer: SecretSanitizer = new SecretSanitizer([])) {
    super(dbPath, MemoryDomain.BUSINESS, sanitizer);
  }
}

/**
 * Memory write policy (spec sections 18, 20.1, 32).
 *
 * Decides what may be persisted and when. Secret safety is enforced here,
 * before any persistence or embedding: content that the Phase 1 redaction
 * boundary would alter is rejected outright rather than stored "sanitized
 * only" — the raw value must never reach a store or an embedding call.
 */

import { redactText } from "../security/redaction";

/** Credential-shaped content that must never be persisted or embedded. */
const CREDENTIAL_PATTERNS: RegExp[] = [
  /eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/, // JWT
  /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/,
  /sk-[A-Za-z0-9_-]{8,}/,
  /gh[pousr]_[A-Za-z0-9]{20,}/,
  /github_pat_[A-Za-z0-9_]{20,}/,
];

/** True when free-form text contains credential-like content. */
export function hasSecretLikeContent(text: string): boolean {
  if (!text) return false;
  if (CREDENTIAL_PATTERNS.some((pattern) => pattern.test(text))) return true;
  // Anything the centralized redaction boundary would alter is secret-like.
  return redactText(text, []) !== text;
}

/** Stronger: text that is *primarily* a secret (short credential blob). */
export function isCredentialBlob(text: string): boolean {
  if (!text) return false;
  const trimmed = text.trim();
  if (trimmed.length < 8 || trimmed.length > 200) return false;
  return /^[A-Za-z0-9_\-]{16,}$/.test(trimmed) || /^Bearer\s+/.test(trimmed);
}

export interface CandidateWritePolicy {
  confidenceThreshold: number;
  importanceThreshold: number;
  minCandidateChars: number;
  maxCandidateChars: number;
}

export const DEFAULT_CANDIDATE_POLICY: CandidateWritePolicy = {
  confidenceThreshold: 0.6,
  importanceThreshold: 0.2,
  minCandidateChars: 12,
  maxCandidateChars: 2000,
};

export type CandidateVerdict =
  | { action: "store" }
  | { action: "reject"; reason: "secret" | "too_short" | "too_long" }
  | { action: "skip"; reason: "low_confidence" | "low_importance" | "should_store_false" | "too_short" };

export interface CandidateLike {
  text: string;
  confidence: number;
  importance: number;
  should_store: boolean;
}

/** Policy gate for extraction candidates (spec section 20.1). */
export function decideCandidate(
  candidate: CandidateLike,
  policy: CandidateWritePolicy = DEFAULT_CANDIDATE_POLICY,
): CandidateVerdict {
  if (!candidate.should_store) return { action: "skip", reason: "should_store_false" };
  const text = candidate.text?.trim() ?? "";
  if (!text) return { action: "skip", reason: "should_store_false" };
  if (hasSecretLikeContent(text) || isCredentialBlob(text)) {
    return { action: "reject", reason: "secret" };
  }
  if (text.length < policy.minCandidateChars) return { action: "skip", reason: "too_short" };
  if (text.length > policy.maxCandidateChars) return { action: "reject", reason: "too_long" };
  if (candidate.confidence < policy.confidenceThreshold) return { action: "skip", reason: "low_confidence" };
  if (candidate.importance < policy.importanceThreshold) return { action: "skip", reason: "low_importance" };
  return { action: "store" };
}

/** TEMPORARY memories get a TTL; others live until superseded/forgotten. */
export function expiryForType(type: string, temporaryTtlSeconds: number, now = new Date()): string | undefined {
  if (type === "TEMPORARY" && temporaryTtlSeconds > 0) {
    return new Date(now.getTime() + temporaryTtlSeconds * 1000).toISOString();
  }
  return undefined;
}

/**
 * Deduplication + supersession trigger (spec sections 21, 22).
 *
 * Order: normalize -> exact content_hash -> same-subject/type semantic
 * similarity -> update provenance (equivalent) | supersede (explicit
 * correction) | create. Superseded memories remain in the store for audit but
 * are excluded from normal retrieval.
 */

import { cosineSimilarity, EmbeddingBatch, EmbeddingGateway } from "./embeddings/contracts";
import {
  MemoryItem,
  MemoryStore,
  MemoryType,
  MemoryWrite,
} from "./contracts";
import { normalizeForCompare } from "./ingestion/normalizer";

export type DedupeAction = "created" | "updated" | "superseded";

export interface DedupeOutcome {
  action: DedupeAction;
  item: MemoryItem;
  /** Canonical-text embedding batch (for chunk reuse by the caller). */
  batch: EmbeddingBatch;
}

/** Semantic similarity above this = same fact rephrased. */
export const SAME_FACT_SIMILARITY = 0.85;
/** Below this, same-subject texts are treated as unrelated (both kept). */
export const MIN_RELATED_SIMILARITY = 0.5;

const SUBJECT_SCOPED_TYPES: readonly MemoryType[] = [
  MemoryType.SEMANTIC,
  MemoryType.PROJECT,
  MemoryType.PROCEDURAL,
  MemoryType.EPISODIC,
];

/** Words that may differ between two phrasings of the same fact. */
const STOPWORDS = new Set([
  "this", "that", "with", "from", "have", "were", "will", "would", "about",
  "their", "there", "which", "when", "than", "then", "them", "they", "your",
  "ours", "yours", "hers", "their", "being", "been", "into", "over", "only",
  "very", "just", "also", "more", "most", "some", "such", "each", "both",
  "these", "those", "while", "after", "before", "between", "during",
]);

/** Token-level content difference (words of >= 4 chars, excluding stopwords). */
function contentDifference(a: string, b: string): string[] {
  const tokensA = new Set(normalizeForCompare(a).split(/\s+/).filter(Boolean));
  const tokensB = new Set(normalizeForCompare(b).split(/\s+/).filter(Boolean));
  const diff = new Set<string>([...tokensA, ...tokensB].filter((t) => !(tokensA.has(t) && tokensB.has(t))));
  return [...diff].filter((t) => t.length >= 4 && !STOPWORDS.has(t));
}

export class DedupeService {
  private readonly embeddings: EmbeddingGateway;

  constructor(embeddings: EmbeddingGateway) {
    this.embeddings = embeddings;
  }

  /**
   * Resolve a new memory write against the domain store. When the write is
   * created or supersedes an old memory, the returned item is the persisted
   * ACTIVE item and the caller is responsible for writing its chunks.
   */
  async resolve(store: MemoryStore, write: MemoryWrite): Promise<DedupeOutcome> {
    // 1. Exact content hash — the dominant duplicate signal (no embedding needed).
    const exact = await store.findActiveByHash(write.content_hash);
    if (exact) {
      await store.touchVerified(exact.id);
      return {
        action: "updated",
        item: exact,
        batch: { provider: "", model: write.embedding_model, version: write.embedding_version, dimensions: 0, vectors: [] },
      };
    }

    // 2. Embed canonical text once; stamp model/version on the write.
    const batch = await this.embeddings.embed([write.canonical_text]);
    const queryVector = batch.vectors[0] ?? [];
    write.embedding_model = batch.model;
    write.embedding_version = batch.version;

    // 3. Same subject + type semantic comparison.
    if (write.subject_key && SUBJECT_SCOPED_TYPES.includes(write.type)) {
      const candidates = await store.findActiveBySubject(write.subject_key, write.type);
      if (candidates.length > 0) {
        const candidateBatch = await this.embeddings.embed(candidates.map((candidate) => candidate.canonical_text));
        let best: { item: MemoryItem; similarity: number } | undefined;
        for (let i = 0; i < candidates.length; i++) {
          const similarity = cosineSimilarity(queryVector, candidateBatch.vectors[i] ?? []);
          if (!best || similarity > best.similarity) {
            best = { item: candidates[i] as MemoryItem, similarity };
          }
        }
        if (best && best.similarity >= SAME_FACT_SIMILARITY) {
          // Highly similar: same fact unless a content word changed (correction).
          const contentDiff = contentDifference(write.canonical_text, best.item.canonical_text);
          if (contentDiff.length === 0 || write.source_type !== "USER_EXPLICIT") {
            await store.touchVerified(best.item.id);
            return { action: "updated", item: best.item, batch };
          }
          // Explicit user correction with a new content word: supersede.
          const replacement = await store.supersede(best.item.id, write);
          return { action: "superseded", item: replacement, batch };
        }
        if (best && best.similarity >= MIN_RELATED_SIMILARITY) {
          if (write.source_type === "USER_EXPLICIT") {
            // Explicit user statements are corrections with authority over
            // older memories.
            const replacement = await store.supersede(best.item.id, write);
            return { action: "superseded", item: replacement, batch };
          }
          // Re-verified inference: update provenance instead of duplicating.
          await store.touchVerified(best.item.id);
          return { action: "updated", item: best.item, batch };
        }
      }
    }

    // 4. New memory.
    const item = await store.put(write);
    return { action: "created", item, batch };
  }
}
